    @override_settings(AUTH_USER_MODEL="auth_tests.CustomUserNoNaturalKey")
    def test_swappable_user_no_natural_key_duplicate_allowed(self):
        """Without get_by_natural_key,
        duplicate username validation is skipped."""
        new_io = StringIO()
        call_command(
            "createsuperuser",
            interactive=False,
            email="joe@somewhere.org",
            stdout=new_io,
        )
        # Creating a second user with the same email won't be caught by
        # _validate_username since there's no get_by_natural_key; it will
        # fail at the database level instead due to the unique constraint.
        with self.assertRaises(IntegrityError):
            call_command(
                "createsuperuser",
                interactive=False,
                email="joe@somewhere.org",
                stdout=new_io,
            )

    def test_skip_if_not_in_TTY(self):
        """
        If the command is not called from a TTY, it should be skipped and a
        message should be displayed (#7423).
        """

        class FakeStdin:
            """A fake stdin object that has isatty() return False."""

            def isatty(self):
                return False

        out = StringIO()
        call_command(
            "createsuperuser",
            stdin=FakeStdin(),
            stdout=out,
            interactive=True,
        )

        self.assertEqual(User._default_manager.count(), 0)
        self.assertIn("Superuser creation skipped", out.getvalue())

    def test_passing_stdin(self):
        """
        You can pass a stdin object as an option and it should be
        available on self.stdin.
        If no such option is passed, it defaults to sys.stdin.
        """
        sentinel = object()
        command = createsuperuser.Command()
        call_command(
            command,
            stdin=sentinel,
            interactive=False,
            verbosity=0,
            username="janet",
            email="janet@example.com",
        )
        self.assertIs(command.stdin, sentinel)

        command = createsuperuser.Command()
        call_command(
            command,
            interactive=False,
            verbosity=0,
            username="joe",
            email="joe@example.com",
        )
        self.assertIs(command.stdin, sys.stdin)

