import inspect
import sys
import warnings
from contextlib import contextmanager

from django.test import SimpleTestCase
from django.utils.deprecation import RemovedInNextVersionWarning

from . import internal


class WarnAboutExternalUseTests(SimpleTestCase):
    @contextmanager
    def assertNotWarns(self, category, **kwargs):
        with warnings.catch_warnings(record=True) as caught_warnings:
            warnings.filterwarnings("always", category=category, **kwargs)
            yield caught_warnings
        self.assertEqual([str(warning) for warning in caught_warnings], [])

    def assertWarningPointsHere(self, warning, *, offset=-1):
        caller_frame = inspect.currentframe().f_back
        self.assertEqual(warning.filename, caller_frame.f_code.co_filename)
        self.assertEqual(warning.lineno, caller_frame.f_lineno + offset)

    def test_external_use_warns(self):
        msg = "This is deprecated."
        with self.assertWarnsMessage(RemovedInNextVersionWarning, msg) as warning:
            internal.deprecated_function(msg, RemovedInNextVersionWarning)
        self.assertWarningPointsHere(warning)

    def test_internal_use_does_not_warn(self):
        with self.assertNotWarns(RemovedInNextVersionWarning):
            internal.one_indirection("This is deprecated.", RemovedInNextVersionWarning)

    def test_external_skip_frames_warns(self):
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            internal.one_indirection(skip_frames=1)
        self.assertWarningPointsHere(warning)

    def test_internal_skip_frames_does_not_warn(self):
        with self.assertNotWarns(RemovedInNextVersionWarning):
            internal.two_indirections(skip_frames=1)

    def test_internal_skip_multiple_frames_does_not_warn(self):
        with self.assertNotWarns(RemovedInNextVersionWarning):
            internal.three_indirections(skip_frames=2)

    def test_external_skip_module_name_warns(self):
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            internal.two_indirections(skip_name_prefixes=internal.__name__)
        self.assertWarningPointsHere(warning)

    def test_internal_skip_module_name_does_not_warn(self):
        # Treat only the current test module as "internal" for this test.
        with self.assertNotWarns(RemovedInNextVersionWarning):
            internal.two_indirections(
                skip_name_prefixes=internal.__name__,
                internal_modules=(__name__,),
            )

    def test_skip_fully_qualified_name(self):
        fqname = f"{internal.__name__}.Class"
        instance = internal.Class()
        for case in ("deprecated_method", "one_indirection", "two_indirections"):
            method = getattr(instance, case)
            with self.subTest(use="external warns", case=case):
                with self.assertWarnsMessage(
                    RemovedInNextVersionWarning, "Message"
                ) as warning:
                    method(skip_name_prefixes=fqname)
                self.assertWarningPointsHere(warning)
            with (
                self.subTest(use="internal does not warn", case=case),
                self.assertNotWarns(RemovedInNextVersionWarning),
            ):
                # Treat only the current test module as "internal".
                method(skip_name_prefixes=fqname, internal_modules=(__name__,))

    def test_skip_name_prefixes_tuple(self):
        prefixes = (
            internal.__name__,
            "django.utils.deprecation.deprecate_posargs",
        )
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            internal.call_decorated(skip_name_prefixes=prefixes)
        self.assertWarningPointsHere(warning)

    def test_skip_name_prefixes_is_applied_before_skip_frames(self):
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            # Stack frames:
            # - deprecated_function()
            # - one_indirection() -- ignored by skip_name_prefixes
            # - two_indirections() -- ignored by skip_frames=1
            # - this test case -- effective caller, is external
            internal.two_indirections(
                skip_name_prefixes=f"{internal.__name__}.one_indirection",
                skip_frames=1,
            )
        self.assertWarningPointsHere(warning, offset=-4)

    def test_skip_name_prefixes_is_not_applied_after_skip_frames(self):
        with self.assertNotWarns(RemovedInNextVersionWarning):
            # Stack frames:
            # - deprecated_function()
            # - (skip_name_prefixes does not match here)
            # - one_indirection() -- ignored by skip_frames=1
            # - two_indirections() -- effective caller, is internal
            internal.two_indirections(
                skip_name_prefixes=f"{internal.__name__}.two_indirections",
                skip_frames=1,
            )

    def test_nested_qualname(self):
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            internal.nested(skip_name_prefixes=f"{internal.__name__}.nested")
        self.assertWarningPointsHere(warning)

    def test_does_not_mistake_third_party_packages_for_django(self):
        # Simulate a "django_goodies" package (which is not part of Django)
        # using a deprecated Django feature.
        sys.modules["django.something"] = internal
        self.addCleanup(sys.modules.pop, "django.something", None)
        code = compile(
            (
                "from django.something import deprecated_function\n"
                "\n"
                "def use_deprecated_function(*args, **kwargs):\n"
                "    deprecated_function(*args, **kwargs)\n"
            ),
            filename="/venv/site-packages/django_goodies/__init__.py",
            mode="exec",
        )
        namespace = {"__name__": "django_goodies"}
        exec(code, namespace)
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            # internal_modules=None forces the default modules.
            namespace["use_deprecated_function"](internal_modules=None)
        self.assertEqual(
            warning.filename, "/venv/site-packages/django_goodies/__init__.py"
        )

    def test_internal_modules_must_be_tuple(self):
        with self.assertRaisesMessage(
            TypeError, "internal_modules must be a tuple of module names"
        ):
            internal.deprecated_function(internal_modules="django")

    def test_warns_if_effective_caller_has_no_filename(self):
        # Simulate a frame whose source location can't be identified by
        # compiling with an empty filename.
        code = compile(
            (
                "def use_deprecated_function(*args, **kwargs):\n"
                "    deprecated_function(*args, **kwargs)\n"
            ),
            filename="",
            mode="exec",
        )
        namespace = {"deprecated_function": internal.deprecated_function}
        exec(code, namespace)
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            namespace["use_deprecated_function"]()
        self.assertEqual(warning.filename, "")
        self.assertEqual(warning.lineno, 2)

    def test_handles_skip_frames_overflow(self):
        too_many_frames = len(inspect.stack()) + 20
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            internal.deprecated_function(skip_frames=too_many_frames)
        # In CPython, warning.filename seems to be "<sys>" and warning.lineno
        # is 0. But the exact values are likely implementation-dependent.
        self.assertNotEqual(warning.filename, __file__)

    def test_handles_skip_name_prefixes_overflow(self):
        with self.assertWarnsMessage(RemovedInNextVersionWarning, "Message") as warning:
            # Every string startswith(""). This will ignore the entire stack.
            internal.deprecated_function(skip_name_prefixes="")
        self.assertNotEqual(warning.filename, __file__)
import inspect
import sys
import warnings
from contextlib import contextmanager

from django.test import SimpleTestCase
from django.utils.deprecation import warn_about_implementation
from django.views.decorators import csrf


class WarnAboutImplementationTests(SimpleTestCase):
    @contextmanager
    def assertWarnsAboutLine(self, category, message, *, offset):
        caller_frame = inspect.currentframe().f_back.f_back
        with self.assertWarnsMessage(category, message) as warning:
            yield
        self.assertEqual(warning.filename, caller_frame.f_code.co_filename)
        self.assertEqual(warning.lineno, caller_frame.f_lineno + offset)

    def test_function(self):
        def some_function():
            pass

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-3):
            warn_about_implementation("deprecated", Warning, some_function)

    def test_class(self):
        class SomeClass:
            pass

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-3):
            warn_about_implementation("deprecated", Warning, SomeClass)

    def test_class_init(self):
        class SomeClass:
            def __init__(self):
                pass

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-3):
            warn_about_implementation("deprecated", Warning, SomeClass.__init__)

    def test_method(self):
        class SomeClass:
            def some_method(self):
                pass

        for case, target in [
            ("unbound", SomeClass.some_method),
            ("bound", SomeClass().some_method),
        ]:
            with (
                self.subTest(case),
                self.assertWarnsAboutLine(Warning, "deprecated", offset=-9),
            ):
                warn_about_implementation("deprecated", Warning, target)

    def test_subclass_method(self):
        class BaseClass:
            def some_method(self):
                pass

            def issue_warning(self):
                warn_about_implementation("deprecated", Warning, self.some_method)

        class SubClass(BaseClass):
            def some_method(self):
                pass

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-3):
            SubClass().issue_warning()

    def test_my_own_method(self):
        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-1):
            warn_about_implementation("deprecated", Warning, self.test_my_own_method)

    def test_classmethod(self):
        class SomeClass:
            @classmethod
            def some_classmethod(cls):
                pass

        for case, target in [
            ("unbound", SomeClass.some_classmethod),
            ("bound", SomeClass().some_classmethod),
        ]:
            with (
                self.subTest(case),
                self.assertWarnsAboutLine(Warning, "deprecated", offset=-10),
            ):
                warn_about_implementation("deprecated", Warning, target)

    def test_staticmethod(self):
        class SomeClass:
            @staticmethod
            def some_staticmethod():
                pass

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-4):
            warn_about_implementation(
                "deprecated", Warning, SomeClass.some_staticmethod
            )

    def test_property(self):
        class SomeClass:
            @property
            def some_property(self):
                return None

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-4):
            warn_about_implementation(
                "deprecated",
                Warning,
                inspect.getattr_static(SomeClass(), "some_property"),
            )

    def test_decorated_function(self):
        @csrf.csrf_exempt
        @csrf.ensure_csrf_cookie
        def some_view(request):
            pass

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-5):
            warn_about_implementation("deprecated", Warning, some_view)

    def test_decorated_method(self):
        class SomeClass:
            @csrf.csrf_exempt
            @csrf.ensure_csrf_cookie
            def some_method(self):
                pass

        for case, target in [
            ("unbound", SomeClass.some_method),
            ("bound", SomeClass().some_method),
        ]:
            with (
                self.subTest(case),
                self.assertWarnsAboutLine(Warning, "deprecated", offset=-11),
            ):
                warn_about_implementation("deprecated", Warning, target)

    def test_decorated_staticmethod(self):
        class SomeClass:
            @staticmethod
            @csrf.csrf_exempt
            @csrf.ensure_csrf_cookie
            def some_staticmethod():
                pass

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-6):
            warn_about_implementation(
                "deprecated", Warning, SomeClass.some_staticmethod
            )

    def test_no_source_file(self):
        # When the source file can't be determined, falls back to warning about
        # the caller. (Builtins like `dict` have no source file.)
        with self.assertWarnsAboutLine(Warning, "deprecated", offset=1):
            warn_about_implementation("deprecated", Warning, dict)

    def test_rejects_invalid_target(self):
        msg = (
            "target must be a function, class, bound method, or unbound descriptor "
            "(classmethod, staticmethod, or property)."
        )
        for invalid in ["string", object(), 123, None]:
            with self.subTest(target=invalid), self.assertRaisesMessage(TypeError, msg):
                warn_about_implementation("deprecated", Warning, invalid)

    def test_respects_warning_registry(self):
        def some_function():
            pass

        # The "default" action only works correctly when warn_explicit() is
        # called with the correct module and warning registry. (This test must
        # use "default" or "module", not "once". CPython has an undocumented
        # optimization for "once" that uses a global registry.)
        with warnings.catch_warnings(record=True, action="default") as captured:
            warn_about_implementation("deprecated", Warning, some_function)
            self.assertEqual(len(captured), 1)

            captured.clear()
            warn_about_implementation("deprecated", Warning, some_function)
            self.assertEqual(len(captured), 0)

    def test_creates_warning_registry_if_needed(self):
        def some_function():
            pass

        module = sys.modules[some_function.__module__]
        if hasattr(module, "__warningregistry__"):
            old_registry = module.__warningregistry__
            del module.__warningregistry__
        else:
            old_registry = None

        try:
            with warnings.catch_warnings(record=True, action="default") as captured:
                warn_about_implementation("deprecated", Warning, some_function)
                warn_about_implementation("deprecated", Warning, some_function)

            self.assertEqual(len(captured), 1)
            self.assertIsInstance(module.__warningregistry__, dict)
            self.assertNotEqual(module.__warningregistry__, {})
        finally:
            if old_registry is not None:
                module.__warningregistry__ = old_registry
            elif hasattr(module, "__warningregistry__"):
                del module.__warningregistry__

    def test_missing_module(self):
        def some_function():
            pass

        some_function.__module__ = "not_a_module"

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=-5):
            warn_about_implementation("deprecated", Warning, some_function)

    def test_non_standard_module(self):
        sys.modules["sealed_module"] = type("SealedModule", (), {"__slots__": ()})()
        self.addCleanup(sys.modules.pop, "sealed_module")

        def some_function():
            pass

        some_function.__module__ = "sealed_module"

        with self.assertWarnsAboutLine(Warning, "deprecated", offset=2):
            # Module is not inspectable, so the warning is issued generically.
            warn_about_implementation("deprecated", Warning, some_function)
import os
import warnings
from pathlib import Path

import django
from django.test import SimpleTestCase
from django.utils.deprecation import (
    RemovedAfterNextVersionWarning,
    RenameMethodsBase,
    django_file_prefixes,
)


class DjangoFilePrefixesTests(SimpleTestCase):
    def setUp(self):
        django_file_prefixes.cache_clear()
        self.addCleanup(django_file_prefixes.cache_clear)

    def test_no_file(self):
        orig_file = django.__file__
        try:
            # Depending on the cwd, Python might give a local checkout
            # precedence over installed Django, producing None.
            django.__file__ = None
            self.assertEqual(django_file_prefixes(), ())
            del django.__file__
            self.assertEqual(django_file_prefixes(), ())
        finally:
            django.__file__ = orig_file

    def test_with_file(self):
        prefixes = django_file_prefixes()
        self.assertIsInstance(prefixes, tuple)
        self.assertEqual(len(prefixes), 1)
        self.assertTrue(prefixes[0].endswith(f"{os.path.sep}django{os.path.sep}"))

    def test_does_not_match_packages_prefixed_with_django(self):
        other_file = Path(django.__file__).parent.parent / "djangoextra" / "__init__.py"
        self.assertFalse(str(other_file).startswith(django_file_prefixes()))


class RenameManagerMethods(RenameMethodsBase):
    renamed_methods = (("old", "new", DeprecationWarning),)


class RenameMethodsTests(SimpleTestCase):
    """
    Tests the `RenameMethodsBase` type introduced to rename `get_query_set`
    to `get_queryset` across the code base following #15363.
    """

    def test_class_definition_warnings(self):
        """
        Ensure a warning is raised upon class definition to suggest renaming
        the faulty method.
        """
        msg = "`Manager.old` method should be renamed `new`."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:

            class Manager(metaclass=RenameManagerMethods):
                def old(self):
                    pass

        self.assertEqual(ctx.filename, __file__)

    def test_get_new_defined(self):
        """
        Ensure `old` complains and not `new` when only `new` is defined.
        """

        class Manager(metaclass=RenameManagerMethods):
            def new(self):
                pass

        manager = Manager()

        with warnings.catch_warnings(record=True) as recorded:
            warnings.simplefilter("always")
            manager.new()
        self.assertEqual(len(recorded), 0)

        msg = "`Manager.old` is deprecated, use `new` instead."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:
            manager.old()
        self.assertEqual(ctx.filename, __file__)

    def test_get_old_defined(self):
        """
        Ensure `old` complains when only `old` is defined.
        """
        msg = "`Manager.old` method should be renamed `new`."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:

            class Manager(metaclass=RenameManagerMethods):
                def old(self):
                    pass

        self.assertEqual(ctx.filename, __file__)

        manager = Manager()

        with warnings.catch_warnings(record=True) as recorded:
            warnings.simplefilter("always")
            manager.new()
        self.assertEqual(len(recorded), 0)

        msg = "`Manager.old` is deprecated, use `new` instead."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:
            manager.old()
        self.assertEqual(ctx.filename, __file__)

    def test_deprecated_subclass_renamed(self):
        """
        Ensure the correct warnings are raised when a class that didn't rename
        `old` subclass one that did.
        """

        class Renamed(metaclass=RenameManagerMethods):
            def new(self):
                pass

        msg = "`Deprecated.old` method should be renamed `new`."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:

            class Deprecated(Renamed):
                def old(self):
                    super().old()

        self.assertEqual(ctx.filename, __file__)

        deprecated = Deprecated()

        msg = "`Renamed.old` is deprecated, use `new` instead."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:
            deprecated.new()
        self.assertEqual(ctx.filename, __file__)

        msg = "`Deprecated.old` is deprecated, use `new` instead."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:
            deprecated.old()
        self.assertEqual(ctx.filename, __file__)

    def test_renamed_subclass_deprecated(self):
        """
        Ensure the correct warnings are raised when a class that renamed
        `old` subclass one that didn't.
        """
        msg = "`Deprecated.old` method should be renamed `new`."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:

            class Deprecated(metaclass=RenameManagerMethods):
                def old(self):
                    pass

        self.assertEqual(ctx.filename, __file__)

        class Renamed(Deprecated):
            def new(self):
                super().new()

        renamed = Renamed()

        with warnings.catch_warnings(record=True) as recorded:
            warnings.simplefilter("always")
            renamed.new()
        self.assertEqual(len(recorded), 0)

        msg = "`Renamed.old` is deprecated, use `new` instead."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:
            renamed.old()
        self.assertEqual(ctx.filename, __file__)

    def test_deprecated_subclass_renamed_and_mixins(self):
        """
        Ensure the correct warnings are raised when a subclass inherit from a
        class that renamed `old` and mixins that may or may not have renamed
        `new`.
        """

        class Renamed(metaclass=RenameManagerMethods):
            def new(self):
                pass

        class RenamedMixin:
            def new(self):
                super().new()

        class DeprecatedMixin:
            def old(self):
                super().old()

        msg = "`DeprecatedMixin.old` method should be renamed `new`."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:

            class Deprecated(DeprecatedMixin, RenamedMixin, Renamed):
                pass

        self.assertEqual(ctx.filename, __file__)

        deprecated = Deprecated()

        msg = "`RenamedMixin.old` is deprecated, use `new` instead."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:
            deprecated.new()
        self.assertEqual(ctx.filename, __file__)

        msg = "`DeprecatedMixin.old` is deprecated, use `new` instead."
        with self.assertWarnsMessage(DeprecationWarning, msg) as ctx:
            deprecated.old()
        self.assertEqual(ctx.filename, __file__)

    def test_removedafternextversionwarning_pending(self):
        self.assertTrue(
            issubclass(RemovedAfterNextVersionWarning, PendingDeprecationWarning)
        )
import weakref
from types import TracebackType
from unittest import mock

from django.dispatch import Signal, receiver
from django.dispatch.dispatcher import _make_id
from django.test import SimpleTestCase
from django.test.utils import garbage_collect, override_settings


def receiver_1_arg(val, **kwargs):
    return val


class Callable:
    def __call__(self, val, **kwargs):
        return val

    def a(self, val, **kwargs):
        return val


a_signal = Signal()
b_signal = Signal()
c_signal = Signal()
d_signal = Signal(use_caching=True)


class DispatcherTests(SimpleTestCase):
    def assertTestIsClean(self, signal):
        """Assert that everything has been cleaned up automatically"""
        # Note that dead weakref cleanup happens as side effect of using
        # the signal's receivers through the signals API. So, first do a
        # call to an API method to force cleanup.
        self.assertFalse(signal.has_listeners())
        self.assertEqual(signal.receivers, [])

    @override_settings(DEBUG=True)
    def test_cannot_connect_no_kwargs(self):
        def receiver_no_kwargs(sender):
            pass

        msg = "Signal receivers must accept keyword arguments (**kwargs)."
        with self.assertRaisesMessage(ValueError, msg):
            a_signal.connect(receiver_no_kwargs)
        self.assertTestIsClean(a_signal)

    @override_settings(DEBUG=True)
    def test_cannot_connect_non_callable(self):
        msg = "Signal receivers must be callable."
        with self.assertRaisesMessage(TypeError, msg):
            a_signal.connect(object())
        self.assertTestIsClean(a_signal)

    def test_send(self):
        a_signal.connect(receiver_1_arg, sender=self)
        result = a_signal.send(sender=self, val="test")
        self.assertEqual(result, [(receiver_1_arg, "test")])
        a_signal.disconnect(receiver_1_arg, sender=self)
        self.assertTestIsClean(a_signal)

    def test_send_no_receivers(self):
        result = a_signal.send(sender=self, val="test")
        self.assertEqual(result, [])

    def test_send_connected_no_sender(self):
        a_signal.connect(receiver_1_arg)
        result = a_signal.send(sender=self, val="test")
        self.assertEqual(result, [(receiver_1_arg, "test")])
        a_signal.disconnect(receiver_1_arg)
        self.assertTestIsClean(a_signal)

    def test_send_different_no_sender(self):
        a_signal.connect(receiver_1_arg, sender=object)
        result = a_signal.send(sender=self, val="test")
        self.assertEqual(result, [])
        a_signal.disconnect(receiver_1_arg, sender=object)
        self.assertTestIsClean(a_signal)

    def test_unweakrefable_sender(self):
        sender = object()
        a_signal.connect(receiver_1_arg, sender=sender)
        result = a_signal.send(sender=sender, val="test")
        self.assertEqual(result, [(receiver_1_arg, "test")])
        a_signal.disconnect(receiver_1_arg, sender=sender)
        self.assertTestIsClean(a_signal)

    def test_garbage_collected_receiver(self):
        a = Callable()
        a_signal.connect(a.a, sender=self)
        del a
        garbage_collect()
        result = a_signal.send(sender=self, val="test")
        self.assertEqual(result, [])
        self.assertTestIsClean(a_signal)

    def test_garbage_collected_sender(self):
        signal = Signal()

        class Sender:
            pass

        def make_id(target):
            """
            Simulate id() reuse for distinct senders with non-overlapping
            lifetimes that would require memory contention to reproduce.
            """
            if isinstance(target, Sender):
                return 0
            return _make_id(target)

        def first_receiver(attempt, **kwargs):
            return attempt

        def second_receiver(attempt, **kwargs):
            return attempt

        with mock.patch("django.dispatch.dispatcher._make_id", make_id):
            sender = Sender()
            signal.connect(first_receiver, sender)
            result = signal.send(sender, attempt="first")
            self.assertEqual(result, [(first_receiver, "first")])

            del sender
            garbage_collect()

            sender = Sender()
            signal.connect(second_receiver, sender)
            result = signal.send(sender, attempt="second")
            self.assertEqual(result, [(second_receiver, "second")])

    def test_cached_garbaged_collected(self):
        """
        Make sure signal caching sender receivers don't prevent garbage
        collection of senders.
        """

        class sender:
            pass

        wref = weakref.ref(sender)
        d_signal.connect(receiver_1_arg)
        d_signal.send(sender, val="garbage")
        del sender
        garbage_collect()
        try:
            self.assertIsNone(wref())
        finally:
            # Disconnect after reference check since it flushes the tested
            # cache.
            d_signal.disconnect(receiver_1_arg)

    def test_multiple_registration(self):
        a = Callable()
        a_signal.connect(a)
        a_signal.connect(a)
        a_signal.connect(a)
        a_signal.connect(a)
        a_signal.connect(a)
        a_signal.connect(a)
        result = a_signal.send(sender=self, val="test")
        self.assertEqual(len(result), 1)
        self.assertEqual(len(a_signal.receivers), 1)
        del a
        del result
        garbage_collect()
        self.assertTestIsClean(a_signal)

    def test_uid_registration(self):
        def uid_based_receiver_1(**kwargs):
            pass

        def uid_based_receiver_2(**kwargs):
            pass

        a_signal.connect(uid_based_receiver_1, dispatch_uid="uid")
        a_signal.connect(uid_based_receiver_2, dispatch_uid="uid")
        self.assertEqual(len(a_signal.receivers), 1)
        a_signal.disconnect(dispatch_uid="uid")
        self.assertTestIsClean(a_signal)

    def test_send_robust_success(self):
        a_signal.connect(receiver_1_arg)
        result = a_signal.send_robust(sender=self, val="test")
        self.assertEqual(result, [(receiver_1_arg, "test")])
        a_signal.disconnect(receiver_1_arg)
        self.assertTestIsClean(a_signal)

    def test_send_robust_no_receivers(self):
        result = a_signal.send_robust(sender=self, val="test")
        self.assertEqual(result, [])

    def test_send_robust_ignored_sender(self):
        a_signal.connect(receiver_1_arg)
        result = a_signal.send_robust(sender=self, val="test")
        self.assertEqual(result, [(receiver_1_arg, "test")])
        a_signal.disconnect(receiver_1_arg)
        self.assertTestIsClean(a_signal)

    def test_send_robust_fail(self):
        def fails(val, **kwargs):
            raise ValueError("this")

        a_signal.connect(fails)
        try:
            with self.assertLogs("django.dispatch", "ERROR") as cm:
                result = a_signal.send_robust(sender=self, val="test")
            err = result[0][1]
            self.assertIsInstance(err, ValueError)
            self.assertEqual(err.args, ("this",))
            self.assertIs(hasattr(err, "__traceback__"), True)
            self.assertIsInstance(err.__traceback__, TracebackType)

            log_record = cm.records[0]
            self.assertEqual(
                log_record.getMessage(),
                "Error calling "
                "DispatcherTests.test_send_robust_fail.<locals>.fails in "
                "Signal.send_robust() (this)",
            )
            self.assertIsNotNone(log_record.exc_info)
            _, exc_value, _ = log_record.exc_info
            self.assertIsInstance(exc_value, ValueError)
            self.assertEqual(str(exc_value), "this")
        finally:
            a_signal.disconnect(fails)
        self.assertTestIsClean(a_signal)

    def test_disconnection(self):
        receiver_1 = Callable()
        receiver_2 = Callable()
        receiver_3 = Callable()
        a_signal.connect(receiver_1)
        a_signal.connect(receiver_2)
        a_signal.connect(receiver_3)
        a_signal.disconnect(receiver_1)
        del receiver_2
        garbage_collect()
        a_signal.disconnect(receiver_3)
        self.assertTestIsClean(a_signal)

    def test_values_returned_by_disconnection(self):
        receiver_1 = Callable()
        receiver_2 = Callable()
        a_signal.connect(receiver_1)
        receiver_1_disconnected = a_signal.disconnect(receiver_1)
        receiver_2_disconnected = a_signal.disconnect(receiver_2)
        self.assertTrue(receiver_1_disconnected)
        self.assertFalse(receiver_2_disconnected)
        self.assertTestIsClean(a_signal)

    def test_has_listeners(self):
        self.assertFalse(a_signal.has_listeners())
        self.assertFalse(a_signal.has_listeners(sender=object()))
        receiver_1 = Callable()
        a_signal.connect(receiver_1)
        self.assertTrue(a_signal.has_listeners())
        self.assertTrue(a_signal.has_listeners(sender=object()))
        a_signal.disconnect(receiver_1)
        self.assertFalse(a_signal.has_listeners())
        self.assertFalse(a_signal.has_listeners(sender=object()))


class ReceiverTestCase(SimpleTestCase):
    def test_receiver_single_signal(self):
        @receiver(a_signal)
        def f(val, **kwargs):
            self.state = val

        self.state = False
        a_signal.send(sender=self, val=True)
        self.assertTrue(self.state)

    def test_receiver_signal_list(self):
        @receiver([a_signal, b_signal, c_signal])
        def f(val, **kwargs):
            self.state.append(val)

        self.state = []
        a_signal.send(sender=self, val="a")
        c_signal.send(sender=self, val="c")
        b_signal.send(sender=self, val="b")
        self.assertIn("a", self.state)
        self.assertIn("b", self.state)
        self.assertIn("c", self.state)
from django.db import models


