        self.assertFKExists(
            f"{app_label}_related",
            ["primary_id"],
            (f"{app_label}_primary", "code"),
        )
        self.assertFKExists(
            f"{app_label}_dependent",
            ["related_id"],
            (f"{app_label}_related", "primary_id"),
        )

