        self.assertEqual(definition[0], "AlterConstraint")
        self.assertEqual(definition[1], [])
        self.assertEqual(
            definition[2],
            {
                "model_name": "Pony",
                "name": "test_alter_constraint_pony_fields_uq",
                "constraint": uq_constraint,
            },
        )

